functions.deleteSelection:
function deleteSelection2() {
  const rootState = this.call("getRootState");
  const sel = rootState.activeSelection;
  if (!sel) return;
  if (sel.type === "node") {
    const nodeId = sel.id;
    const newNodes = (rootState.nodes || []).filter((n) => n.id !== nodeId);
    const newConns = (rootState.connections || []).filter(
      (c) => c.sourceNodeId !== nodeId && c.targetNodeId !== nodeId
    );
    rootState.update({
      nodes: newNodes,
      connections: newConns,
      activeSelection: null
    });
  } else if (sel.type === "wire") {
    const wireId = sel.id;
    const newConns = (rootState.connections || []).filter((c) => c.id !== wireId);
    rootState.update({
      connections: newConns,
      activeSelection: null
    });
  }
}

functions.getBezierPath:
function getBezierPath2(x1, y1, x2, y2) {
  const dx = Math.abs(x2 - x1);
  const controlOffset = Math.max(dx * 0.5, 80);
  const cx1 = x1 + controlOffset;
  const cy1 = y1;
  const cx2 = x2 - controlOffset;
  const cy2 = y2;
  return `M ${x1} ${y1} C ${cx1} ${cy1}, ${cx2} ${cy2}, ${x2} ${y2}`;
}

functions.getRootState:
function() {
  let current = this;
  while (current) {
    if (current.state && current.state.nodes !== void 0) {
      return current.state;
    }
    current = current.parent;
  }
  return this.state || {};
}

functions.getSocketCoords:
function getSocketCoords2(rootState, nodeId, socketId) {
  if (!rootState) return null;
  const rawState = typeof rootState.parse === "function" ? rootState.parse() : rootState;
  const nodes = rawState.nodes || [];
  const node = nodes.find((n) => n.id === nodeId);
  if (!node) return null;
  const inputs = Array.from(node.inputs || []);
  const outputs = Array.from(node.outputs || []);
  const allSockets = inputs.concat(outputs);
  const socket = allSockets.find((sk) => sk.id === socketId);
  if (!socket) return null;
  return {
    x: node.x + socket.relativeX,
    y: node.y + socket.relativeY
  };
}

functions.getWireCoords:
function getWireCoords2(rootState, sourceNodeId, sourceSocketId, targetNodeId, targetSocketId) {
  const src = this.call("getSocketCoords", rootState, sourceNodeId, sourceSocketId);
  const tgt = this.call("getSocketCoords", rootState, targetNodeId, targetSocketId);
  if (!src || !tgt) return null;
  return { x1: src.x, y1: src.y, x2: tgt.x, y2: tgt.y };
}

functions.loadWorkspace:
function loadWorkspace2(file) {
  if (!file) return;
  const reader = new FileReader();
  const self = this;
  reader.onload = function(e) {
    let data;
    try {
      data = JSON.parse(e.target.result);
    } catch (err) {
      self.call("showToast", "Invalid workflow file format", "error");
      return;
    }
    const isValid = self.call("validateGraph", data);
    if (!isValid) {
      self.call("showToast", "Invalid workflow file format", "error");
      return;
    }
    const s = self.state;
    const root = s.root || s;
    root.update({
      nodes: data.nodes,
      connections: data.connections,
      transform: data.transform,
      activeSelection: null,
      isDraggingNode: false,
      draggingNodeId: null,
      isDraggingWire: false,
      draftWire: null
    });
    self.call("showToast", "Workspace loaded successfully", "success");
  };
  reader.onerror = function() {
    self.call("showToast", "Failed to read file", "error");
  };
  reader.readAsText(file);
}

